"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["31633"],{92823(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.fato_coletado.precondicao_cita_fato_nao_coletado","status":422,"titulo":"A regra de deriva\xe7\xe3o cita um fato que este processo n\xe3o coleta nem deriva"},"descricao":{"codigo":"uniplus.selecao.fato_coletado.precondicao_cita_fato_nao_coletado","requisitos":[],"oQueAconteceu":["Uma regra de deriva\xe7\xe3o calcula um fato a partir de condi\xe7\xf5es sobre outros fatos. A\\ncondi\xe7\xe3o de uma das regras do processo cita um fato que o processo n\xe3o tem. Para\\nesta confer\xeancia, s\xf3 contam como existentes os fatos coletados por itens que n\xe3o\\nest\xe3o dentro de grupo repet\xedvel de nenhum formul\xe1rio e os fatos derivados do\\nprocesso, inclusive os que a distribui\xe7\xe3o de vagas fornece. Um fato que aparece\\napenas como campo de um grupo repet\xedvel n\xe3o conta. A mensagem traz o fato\\nderivado e o fato citado.","Os itens dos formul\xe1rios e as deriva\xe7\xf5es podem mudar depois que a regra foi\\ngravada, e por isso a configura\xe7\xe3o \xe9 conferida ao congelar: na publica\xe7\xe3o e na\\nretifica\xe7\xe3o em ato \xfanico. As pend\xeancias s\xe3o\\navaliadas em ordem fixa e a primeira decide o c\xf3digo: esta vem depois das\\nconfer\xeancias das exig\xeancias documentais, da consequ\xeancia de indeferimento, da\\nrefer\xeancia temporal dos fatos e das regras das modalidades. Nada \xe9 congelado."],"comoResolver":["Escolha o que reflete o edital e repita a opera\xe7\xe3o:","- se o fato n\xe3o \xe9 coletado nem derivado, inclua-o entre os itens de um dos\\n  formul\xe1rios do processo, fora de grupo repet\xedvel\\n  (`PUT .../formularios/{codigo}/itens`);\\n- se o fato s\xf3 existe como campo de um grupo repet\xedvel, ele n\xe3o pode alimentar a\\n  regra: inclua-o tamb\xe9m como item fora de grupo, ou ajuste a regra de deriva\xe7\xe3o\\n  para citar um fato que conte (`PUT .../regras-derivacao`);\\n- se a cita\xe7\xe3o est\xe1 errada, ajuste a regra de deriva\xe7\xe3o para n\xe3o citar o fato\\n  (`PUT .../regras-derivacao`)."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Fato coletado"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);